const fireLizardSheet=new Image();fireLizardSheet.assetSrc='assets/fire-lizard-v1.png';
function beginFireLizard(e){let angle=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.struck=false;e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;e.attack={pattern:'fireSweepingBreath',bespoke:true,windup:1.1,origin:{x:e.x,y:e.y},angle,hit:false,started:false};}
function fireLizardAngle(time){return -Math.PI/3+Math.PI*2/3*Math.max(0,Math.min(1,(time-1.1)/1.4));}
function fireLizardTouches(a,point,from,to){if(to<1.1||from>2.5||dist(a.origin,point)>280+1e-8)return false;let angle=Math.atan2(point.y-a.origin.y,point.x-a.origin.x)-a.angle;angle=Math.atan2(Math.sin(angle),Math.cos(angle));return angle>=fireLizardAngle(Math.max(from,1.1))-Math.PI/18-1e-8&&angle<=fireLizardAngle(Math.min(to,2.5))+Math.PI/18+1e-8;}
const fireLizardAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r7e5')return fireLizardAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='fireSweepingBreath'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=310&&clear){beginFireLizard(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.6;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,130*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}let before=e.elapsed;e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.started&&e.elapsed>=1.1){a.started=true;e.struck=true;playSound('fire',e.x,e.y);}if(!a.hit&&!(p.inv>0)&&fireLizardTouches(a,p,before,e.elapsed)&&lineClear(a.origin,p)){a.hit=true;hurt(82);}if(e.elapsed>=3.4){e.attack=null;e.state='idle';e.t=2.6;}
};
const fireLizardDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r7e5'||!fireLizardSheet.complete||!fireLizardSheet.naturalWidth||!fireLizardSheet.naturalHeight)return fireLizardDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='fireSweepingBreath')f={row:2,col:e.elapsed<1.1?0:e.elapsed<1.8?1:e.elapsed<2.5?2:3};let q=project(e.x,e.y),sw=fireLizardSheet.naturalWidth/4,sh=fireLizardSheet.naturalHeight/3,w=250,h=w*sh/sw,anchor=[.83,.85,.83][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,fireLizardSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(fireLizardSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const fireLizardSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r7e5'?155:fireLizardSizeBase(e);
function drawFireLizardCone(a,angle,half,fill,stroke,reach=280){let q=project(a.origin.x,a.origin.y);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.fillStyle=fill;ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,reach,angle-half,angle+half);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();}
const fireLizardGroundBase=drawGroundEffects;drawGroundEffects=()=>{fireLizardGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r7e5'):enemies)){let a=e.attack;if(e.species!=='r7e5'||e.hp<=0||a?.pattern!=='fireSweepingBreath'||!visibleAt(e.x,e.y))continue;if(e.elapsed<=2.5){drawFireLizardCone(a,a.angle,Math.PI*7/18,'#de713011','#db8e5655');if(e.elapsed<1.1)drawFireLizardCone(a,a.angle-Math.PI/3,Math.PI/18,'#ffb46d22','#eeb270');else{let angle=a.angle+fireLizardAngle(e.elapsed);drawFireLizardCone(a,angle,Math.PI/18,a.hit?'#de7b3533':'#f4783077','#ffbe76');drawFireLizardCone(a,angle,Math.PI/36,'#ffd18b88','#ffe7b1',210+Math.sin(e.elapsed*23)*12);}}else groundRing(e.x,e.y,30,'#9bddcf',2);}};
